import * as pdfjsLib from 'pdfjs-dist';
import { BERTopic } from 'bertopic'; // Assuming you're in an environment with Python/JS interop
import { SentenceTransformer } from 'sentence-transformers'; 

// Set the workerSrc globally to avoid issues with the PDF.js worker
pdfjsLib.GlobalWorkerOptions.workerSrc = `//cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.js`;

const parsePDF = async (file) => {
  const reader = new FileReader();
  reader.readAsArrayBuffer(file);

  return new Promise((resolve, reject) => {
    reader.onload = async function () {
      try {
        const typedArray = new Uint8Array(reader.result);
        const pdf = await pdfjsLib.getDocument(typedArray).promise;

        if (!pdf || !pdf.numPages) {
          reject(new Error('Failed to load PDF document or no pages found.'));
          return;
        }

        let parsedText = '';

        // Loop through all the pages
        for (let i = 1; i <= pdf.numPages; i++) {  // Start from page 1
          const page = await pdf.getPage(i);
          const textContent = await page.getTextContent();

          // Extract text from each page
          const pageText = textContent.items.map((item) => item.str).join(' ');
          parsedText += pageText + '\n';
        }

        resolve(parsedText);
      } catch (error) {
        reject(error); // Catch any errors during parsing
      }
    };

    reader.onerror = function (error) {
      reject(error);
    };
  });
};

// Function to extract topics using BERTopic
const extractTopics = async (text) => {
  // Assuming you're running this in a Python environment or using a similar setup
  // You can interact with the Python model and execute BERTopic code
  const sentenceTransformer = new SentenceTransformer('all-MiniLM-L6-v2');  // You can use any pre-trained model
  const model = new BERTopic();

  // Convert text into a list of sentences (for better topic modeling)
  const sentences = text.split('\n').filter(sentence => sentence.trim());

  // Extract embeddings
  const embeddings = await sentenceTransformer.encode(sentences);

  // Fit the BERTopic model
  const [topics, probs] = model.fit_transform(sentences, embeddings);

  // Get the most relevant topics and return them
  return model.get_topics();
};

// Usage of parsePDF and extractTopics
const handleResumeFile = async (file) => {
  try {
    const parsedText = await parsePDF(file);
    const topics = await extractTopics(parsedText);

    console.log('Extracted Topics:', topics);
  } catch (error) {
    console.error('Error parsing or extracting topics:', error);
  }
};

export { parsePDF, extractTopics, handleResumeFile };
